/**
 * Thumbnail Foto Pengajuan dari `get_thumbnails` (data URI JPEG kecil).
 *
 * Satu permintaan untuk banyak foto, bukan satu per foto: di aplikasi native
 * `<img src="/private/files/...">` tidak bisa dipakai, sedangkan data URI tampil
 * di mana saja. Cache-nya global dan per URL — URL foto unik per unggahan, jadi
 * aman dipakai lintas dokumen dan lintas komponen (daftar, galeri, lightbox).
 */
import { reactive } from 'vue'

const METHOD = '/api/method/juragan.juragan.doctype.data_pengajuan.foto_pengajuan.get_thumbnails'
// Cerminan MAX_THUMBNAILS di foto_pengajuan.py.
const BATCH = 60

// url → data URI, atau '' bila server tidak bisa membuatnya (PDF, gagal dibaca).
export const thumbnails = reactive({})
const inflight = new Set()

const isPdf = (url) => /\.pdf$/i.test(String(url || '').split(/[?#]/)[0])

export function thumbnailOf(url) {
	return thumbnails[url] || ''
}

/**
 * Ambil thumbnail yang belum ada di cache. Gagal tidak dilempar: thumbnail hanya
 * mempercepat tampilan, foto aslinya tetap bisa dibuka lewat viewer.
 */
export async function loadThumbnails(docname, urls) {
	if (!docname) return
	const missing = [...new Set(urls || [])].filter(
		(url) => url && !isPdf(url) && !(url in thumbnails) && !inflight.has(url),
	)
	if (!missing.length) return

	missing.forEach((url) => inflight.add(url))
	try {
		for (let i = 0; i < missing.length; i += BATCH) {
			const batch = missing.slice(i, i + BATCH)
			// null = permintaannya gagal: jangan di-cache, supaya dicoba lagi nanti.
			let result = null
			try {
				const body = new URLSearchParams({ docname, file_urls: JSON.stringify(batch) })
				const response = await fetch(METHOD, {
					method: 'POST',
					credentials: 'include',
					headers: {
						Accept: 'application/json',
						'Content-Type': 'application/x-www-form-urlencoded',
						'X-Frappe-CSRF-Token': window.csrf_token || '',
					},
					body,
				})
				const payload = await response.json().catch(() => ({}))
				if (response.ok && !payload.exc) result = payload.message || {}
			} catch {
				result = null
			}
			if (!result) continue
			for (const url of batch) thumbnails[url] = result[url] || ''
		}
	} finally {
		missing.forEach((url) => inflight.delete(url))
	}
}
